7	import { ApprovalMode } from '../policy/types.js';
8	import { checkExhaustive } from './checks.js';
9	
10	/**
11	 * Returns a human-readable description for an approval mode.
12	 */
13	export function getApprovalModeDescription(mode: ApprovalMode): string {
14	  switch (mode) {
15	    case ApprovalMode.AUTO_EDIT:
16	      return 'Auto-Edit mode (edits will be applied automatically)';
17	    case ApprovalMode.DEFAULT:
18	      return 'Default mode (edits will require confirmation)';
19	    case ApprovalMode.PLAN:
20	      return 'Plan mode (read-only planning)';
21	    case ApprovalMode.YOLO:
22	      return 'YOLO mode (all tool calls auto-approved)';
23	    default:
24	      return checkExhaustive(mode);
25	  }
26	}
27	
28	/**
29	 * Generates a consistent message for plan mode transitions.
30	 */
31	export function getPlanModeExitMessage(
32	  newMode: ApprovalMode,
33	  isManual: boolean = false,
34	): string {
35	  const description = getApprovalModeDescription(newMode);
36	  const prefix = isManual
37	    ? 'User has manually exited Plan Mode.'
38	    : 'Plan approved.';
39	  return `${prefix} Switching to ${description}.`;
40	}
