34	/**
35	 * Helper to format the policy denial error.
36	 */
37	export function getPolicyDenialError(
38	  config: Config,
39	  rule?: PolicyRule,
40	): { errorMessage: string; errorType: ToolErrorType } {
41	  const denyMessage = rule?.denyMessage ? ` ${rule.denyMessage}` : '';
42	  return {
43	    errorMessage: `Tool execution denied by policy.${denyMessage}`,
44	    errorType: ToolErrorType.POLICY_VIOLATION,
45	  };
46	}
