203	/**
204	 * Handles policy updates for standard tools (Shell, Info, etc.), including
205	 * session-level and persistent approvals.
206	 */
207	async function handleStandardPolicyUpdate(
208	  tool: AnyDeclarativeTool,
209	  outcome: ToolConfirmationOutcome,
210	  confirmationDetails: SerializableConfirmationDetails | undefined,
211	  messageBus: MessageBus,
212	  persistScope?: 'workspace' | 'user',
213	  toolInvocation?: AnyToolInvocation,
214	  config?: Config,
215	  modes?: ApprovalMode[],
216	): Promise<void> {
217	  if (
218	    outcome === ToolConfirmationOutcome.ProceedAlways ||
219	    outcome === ToolConfirmationOutcome.ProceedAlwaysAndSave
220	  ) {
221	    const options: PolicyUpdateOptions =
222	      toolInvocation?.getPolicyUpdateOptions?.(outcome) || {};
223	
224	    if (!options.commandPrefix && confirmationDetails?.type === 'exec') {
225	      options.commandPrefix = confirmationDetails.rootCommands;
226	    } else if (!options.argsPattern && confirmationDetails?.type === 'edit') {
227	      const filePath = config
228	        ? makeRelative(confirmationDetails.filePath, config.getTargetDir())
229	        : confirmationDetails.filePath;
230	      options.argsPattern = buildFilePathArgsPattern(filePath);
231	    }
232	
233	    await messageBus.publish({
234	      type: MessageBusType.UPDATE_POLICY,
235	      toolName: tool.name,
236	      persist: outcome === ToolConfirmationOutcome.ProceedAlwaysAndSave,
237	      persistScope,
238	      modes,
239	      ...options,
240	    });
241	  }
242	}
